import type { NativeProps } from 'zerodep-js';

type Equal<X, Y, Yes = true, No = false> =
  (<T>() => T extends X ? 1 : 2) extends <T>() => T extends Y ? 1 : 2 ? Yes : No;
type Declared<T> = {
  [K in keyof T as string extends K ? never : number extends K ? never : symbol extends K ? never : K]: T[K];
};
type ReferenceWritable<T, N = Declared<T>> = {
  [K in keyof N]-?: Equal<{ [P in K]: N[K] }, { -readonly [P in K]: N[K] }, K, never>;
}[keyof N] & keyof T;
type Assert<T extends true> = T;
type Expected<T, K extends string> = `prop:${Extract<ReferenceWritable<T>, K>}`;
type Actual<T extends Element, K extends string> = Extract<keyof NativeProps<T>, `prop:${K}`>;

interface Widget extends HTMLElement {
  mutable: string;
  readonly immutable: number;
  optional?: string;
  readonly optionalReadonly?: string;
  nested: { label: string };
  callback(value: string): string;
}
type WidgetKeys = 'mutable' | 'immutable' | 'optional' | 'optionalReadonly' | 'nested' | 'callback';
export type ObjectKeys = Assert<Equal<Expected<Widget, WidgetKeys>, Actual<Widget, WidgetKeys>>>;
declare class Accessors extends HTMLElement {
  get getterOnly(): string;
  get getterSetter(): string;
  set getterSetter(value: string);
  mutable: string;
  readonly immutable: string;
}
type AccessorKeys = 'getterOnly' | 'getterSetter' | 'mutable' | 'immutable';
export type AccessorCheck = Assert<Equal<Expected<Accessors, AccessorKeys>, Actual<Accessors, AccessorKeys>>>;
interface StringIndex extends Widget { [name: string]: unknown }
interface NumberIndex extends Widget { [index: number]: unknown }
interface SymbolIndex extends Widget { [index: symbol]: unknown }
export type StringIndexCheck = Assert<Equal<Expected<StringIndex, WidgetKeys>, Actual<StringIndex, WidgetKeys>>>;
export type NumberIndexCheck = Assert<Equal<Expected<NumberIndex, WidgetKeys>, Actual<NumberIndex, WidgetKeys>>>;
export type SymbolIndexCheck = Assert<Equal<Expected<SymbolIndex, WidgetKeys>, Actual<SymbolIndex, WidgetKeys>>>;
export type IntersectionCheck = Assert<Equal<Expected<Widget & { readonly extra: string }, WidgetKeys | 'extra'>, Actual<Widget & { readonly extra: string }, WidgetKeys | 'extra'>>>;
export type FormCheck = Assert<Equal<Expected<HTMLFormElement, 'offsetWidth' | 'scrollTop' | 'name'>, Actual<HTMLFormElement, 'offsetWidth' | 'scrollTop' | 'name'>>>;
// select.name 属于模型保留属性，不作为 prop:name 公开；这里只比较非保留键。
export type SelectCheck = Assert<Equal<Expected<HTMLSelectElement, 'offsetWidth' | 'scrollTop'>, Actual<HTMLSelectElement, 'offsetWidth' | 'scrollTop'>>>;
